<template><view class="consent"><checkbox-group @change="emit('update:modelValue',$event.detail.value.includes('agree'))"><label><checkbox class="consent-checkbox" value="agree" :checked="modelValue" color="#184F40"/></label></checkbox-group><text>我已阅读并同意<text class="link" @tap="agreement">《用户协议》</text><text class="link" @tap="privacy">《隐私条款》</text></text></view></template>
<script setup lang="ts">import {request} from '@/api/http';defineProps<{modelValue:boolean}>();const emit=defineEmits<{(e:'update:modelValue',value:boolean):void}>();async function agreement(){try{const r=await request<{content:string}>('/public/registration/agreement');await uni.showModal({title:'用户协议',content:r.content,showCancel:false});}catch{uni.showToast({title:'协议加载失败，请重试',icon:'none'});}}function privacy(){uni.showModal({title:'隐私条款',content:'账号及验证信息用于登录和账号安全；任务、积分及成长记录用于提供成长服务。信息按组织、监护关系和授予权限访问。请妥善保管密码、验证码和登录码。',showCancel:false});}</script>
<style scoped>.consent{display:flex;align-items:center;white-space:nowrap;gap:0;padding:24rpx 0;font-size:21rpx;color:#84958a}.consent .consent-checkbox{transform:scale(.62);width:40rpx}.link{color:#184F40}</style>
